import React, { useState, useMemo } from "react";
import MatchItem from "./MatchItem";

function MatchList({ matches, selectedLeague, orderedLeagues }) {
  // null означает показ всех доступных матчей
  const [selectedDate, setSelectedDate] = useState(null);

  // Генерируем фиксированный набор: Вчера, Сегодня и 5 дней вперед (всего 7 кнопок)
  const dateOptions = useMemo(() => {
    const dates = [];
    for (let i = -1; i <= 5; i++) {
      const d = new Date();
      d.setDate(d.getDate() + i);
      dates.push({
        full: d.toISOString().split("T")[0],
        day: d.getDate(),
        weekday: d.toLocaleDateString("ru-RU", { weekday: "short" }),
        displayDate: d.toLocaleDateString("ru-RU").replace(/\//g, "-"), // Формат ДД-ММ-ГГГГ
      });
    }
    return dates;
  }, []);

  const filteredMatches = useMemo(() => {
    let result = [...matches];
    if (selectedLeague) {
      return result.filter((m) => m.league === selectedLeague);
    }
    if (selectedDate) {
      return result.filter((m) => m.utcDate.split("T")[0] === selectedDate);
    }
    return result;
  }, [matches, selectedLeague, selectedDate]);

  const groupedMatches = useMemo(() => {
    const groups = {};
    filteredMatches.forEach((match) => {
      const leagueCode = match.league;
      if (!groups[leagueCode]) {
        const leagueObj = orderedLeagues.find(
          (l) => l.code === leagueCode || l.name === leagueCode,
        );
        groups[leagueCode] = {
          name: leagueObj ? leagueObj.name : leagueCode,
          order: orderedLeagues.findIndex(
            (l) => l.code === leagueCode || l.name === leagueCode,
          ),
          matches: [],
        };
      }
      groups[leagueCode].matches.push(match);
    });
    return Object.entries(groups).sort((a, b) => a[1].order - b[1].order);
  }, [filteredMatches, orderedLeagues]);

  // Красивое форматирование даты для вывода ошибки
  const formatErrorDate = (dateStr) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split("-");
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full">
      {/* ПАНЕЛЬ ДАТ (Растягивается на всю ширину, без скролла) */}
      {!selectedLeague && (
        <div className="flex items-stretch gap-1 md:gap-2 mb-4 bg-gray-900/40 p-1.5 rounded-2xl border border-gray-800 w-full">
          {/* Кнопка "ВСЕ" */}
          <button
            onClick={() => setSelectedDate(null)}
            className={`flex-1 flex items-center justify-center rounded-xl font-black text-[9px] md:text-[10px] uppercase transition-all ${
              selectedDate === null
                ? "bg-red-600 text-white shadow-lg shadow-red-600/20"
                : "bg-gray-800 text-gray-500 hover:bg-gray-700"
            }`}
          >
            ВСЕ
          </button>

          {/* Список дат (масштабируются flex-1) */}
          {dateOptions.map((d) => (
            <button
              key={d.full}
              onClick={() => setSelectedDate(d.full)}
              className={`flex-1 flex flex-col items-center justify-center min-w-0 h-14 rounded-xl transition-all ${
                selectedDate === d.full
                  ? "bg-red-600 text-white shadow-lg shadow-red-600/20"
                  : "bg-gray-800 text-gray-500 hover:bg-gray-700"
              }`}
            >
              <span className="text-[8px] md:text-[10px] font-black uppercase leading-none mb-1">
                {d.weekday}
              </span>
              <span className="text-xs md:text-base font-black leading-none">
                {d.day}
              </span>
            </button>
          ))}

          {/* Календарь (фиксированная ширина) */}
          <div className="relative flex-shrink-0">
            <input
              type="date"
              className="absolute inset-0 opacity-0 cursor-pointer z-10"
              onChange={(e) => setSelectedDate(e.target.value)}
            />
            <button
              className={`w-12 md:w-14 h-14 flex items-center justify-center rounded-xl transition-colors ${
                selectedDate &&
                !dateOptions.find((d) => d.full === selectedDate)
                  ? "bg-red-600 text-white"
                  : "bg-gray-800 text-gray-500 hover:bg-gray-700"
              }`}
            >
              <svg
                className="w-5 h-5 md:w-6 md:h-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                />
              </svg>
            </button>
          </div>
        </div>
      )}

      {/* ВЫВОД МАТЧЕЙ */}
      {groupedMatches.length === 0 ? (
        <div className="text-center py-20 bg-gray-900/20 rounded-3xl border border-gray-800/50 px-6">
          <div className="mb-4 text-4xl">📡</div>
          <h3 className="text-white font-black uppercase tracking-tighter text-lg mb-2">
            Матчей на {formatErrorDate(selectedDate)} не найдено
          </h3>
          <p className="text-gray-500 text-xs font-bold uppercase tracking-widest leading-relaxed">
            Попробуйте выбрать другой день в календаре{" "}
            <br className="hidden md:block" />
            или воспользуйтесь функцией{" "}
            <span className="text-red-600">сравнения матчей (H2H)</span>
          </p>
        </div>
      ) : (
        groupedMatches.map(([code, league]) => (
          <div key={code} className="mb-4">
            <div className="flex flex-col items-center mb-8">
              <h2 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tighter">
                {league.name}
              </h2>
              {league.matches[0].matchday &&
                league.matches[0].matchday < 100 && (
                  <span className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mt-1">
                    Matchday {league.matches[0].matchday}
                  </span>
                )}
              <div className="w-11 h-1 bg-red-600 mt-2 rounded-full opacity-40"></div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6">
              {league.matches.map((match) => (
                <MatchItem key={match.id} match={match} />
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

export default MatchList;
